def _post_trust_dids_deactivate_sync_batch(
    self, tenant: str
) -> None:
    # 批量登记外部 DID 停用通告：任何失败都返回 HTTP 200。请求体
    # 须恰为 {"items": [项...]}，数组非空且不超过 100 项；请求体
    # 非法（空体、非法 JSON、非对象、字段缺失或多余、items 非数
    # 组、空数组或超过上限）时返回 {"results": [], "reason":
    # "请求..."}。请求级合法时返回 {"results": [...]}，长度与顺
    # 序与输入一致，逐项复用单项登记规则，失败不短路：项结构/字
    # 段错误 400、同 did 异通告 409、锚点/签名失败 200、落盘失
    # 败 500“存储失败”（仅回滚该项）均收敛为单项结果（含
    # http_status 与非空中文 reason），不影响其余项；成功项首
    # 次 201、完全重放 200。显式空 X-Tenant-ID 在此之前由路由
    # 统一判 400。
    try:
        length = int(self.headers.get("Content-Length") or 0)
        raw = self.rfile.read(length) if length > 0 else b""
    except (ValueError, TypeError):
        self._send_json(
            200,
            {"results": [],
             "reason": "请求不合法: 请求体缺失或长度声明非法"},
        )
        return
    except Exception:  # noqa: BLE001
        self._send_json(
            200, {"results": [], "reason": "请求不合法: 请求体读取失败"}
        )
        return
    if not raw:
        self._send_json(
            200, {"results": [], "reason": "请求不合法: 请求体缺失"}
        )
        return
    try:
        data = json.loads(raw.decode("utf-8"))
    except UnicodeDecodeError:
        self._send_json(
            200,
            {"results": [], "reason": "请求不合法: 请求体不是合法 UTF-8 文本"},
        )
        return
    except json.JSONDecodeError:
        self._send_json(
            200, {"results": [], "reason": "请求不合法: 请求体不是合法 JSON"}
        )
        return

    try:
        ok, reason, results = (
            store.sync_did_deactivation_notice_batch(tenant, data)
        )
    except Exception:  # noqa: BLE001 批量登记失败绝不暴露内部细节
        self._send_json(
            200, {"results": [], "reason": "请求不合法: 登记过程发生内部错误"}
        )
        return
    if not ok:
        self._send_json(
            200, {"results": [], "reason": reason or "请求不合法"}
        )
        return
    self._send_json(200, {"results": results})

